// Adds the access_code_hash column required by the test-webpage login flow.
// The plain code is generated by scripts/seed-owners.js and shared with testers
// directly (e.g. WhatsApp). The hash stored here is bcrypt.
//
// Spec note: "add it and tell me — don't silently bolt on columns I haven't seen."
// This column is the only schema addition needed to support email+code login without
// a separate auth service.

exports.shorthands = undefined;

exports.up = (pgm) => {
  pgm.addColumn('owners', {
    access_code_hash: {
      type: 'text',
      // nullable: only test owners that have been seeded will have a code.
    },
  });
};

exports.down = (pgm) => {
  pgm.dropColumn('owners', 'access_code_hash');
};
